member.example:
The following code illustrates how to access the FileName property.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Create image stream from svg
            Stream svgStream = new FileStream("image.svg", FileMode.Open);

            //Create image stream from png
            Stream stream = new FileStream("image.png", FileMode.Open);

            //Add image
            IPictureShape picture = worksheet.Pictures.AddPicture(1, 1, svgStream, stream, 50, 50);

            //Check
            Console.Write(picture.FileName);

            //Save and dispose
            workbook.SaveAs("Shapes.xlsx");
            workbook.Close();
            Console.ReadKey();
        }
//Output will be
//Picture0

The following code illustrates how Picture property can be accessed.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Create image stream from svg
            Stream svgStream = new FileStream("image.svg", FileMode.Open);

            //Create image stream from png
            Stream stream = new FileStream("image.png", FileMode.Open);

            //Add image
            IPictureShape picture = worksheet.Pictures.AddPicture(1, 1, svgStream, stream, 50, 50);

            //Check
            Console.Write(picture.Picture != null);

            //Save and dispose
            workbook.SaveAs("Shapes.xlsx");
            workbook.Close();
            Console.ReadKey();
        }
//Output will be
//True

The following code illustrates how SvgData property can be accessed.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Create image stream from svg
            Stream svgStream = new FileStream("image.svg", FileMode.Open);

            //Create image stream from png
            Stream stream = new FileStream("image.png", FileMode.Open);

            //Add image
            IPictureShape picture = worksheet.Pictures.AddPicture(1, 1, svgStream, stream, 50, 50);

            //Check
            Console.Write(picture.SvgData != null);

            //Save and dispose
            workbook.SaveAs("Shapes.xlsx");
            workbook.Close();
            Console.ReadKey();
        }
//Output will be
//True

The following code illustrates how to get items from group shape.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Open("GroupShapes.xlsx");
            IWorksheet worksheet = workbook.Worksheets[0];

            IShapes shapes = worksheet.Shapes;
            IShape[] groupItems = (shapes[0] as IGroupShape).Items;

            //Save and dispose
            workbook.SaveAs("GroupShapes.xlsx");
            workbook.Close();
        }

The following code illustrates how to access Count property.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Add pictures
            worksheet.Pictures.AddPicture("image.png");
            worksheet.Pictures.AddPicture("image.png");

            //Get count
            Console.Write(worksheet.Pictures.Count);

            //Save and dispose
            workbook.SaveAs("Pictures.xlsx");
            workbook.Close();
            Console.ReadKey();
        }

The following code illustrates how to access an  object in the  collection.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Add picture
            worksheet.Pictures.AddPicture("image.png");

            //Set picture
            IPictureShape picture = worksheet.Pictures[0];

            //Set dimension
            picture.Left = 3;
            picture.Top = 3;
            picture.Height = 50;
            picture.Width = 50;

            //Save and dispose
            workbook.SaveAs("Pictures.xlsx");
            workbook.Close();
        }

The following code illustrates how to access a  object from the  collection.

        using (ExcelEngine excelEngine = new ExcelEngine())
        {
            //Create worksheet
            IApplication application = excelEngine.Excel;
            application.DefaultVersion = ExcelVersion.Excel2013;
            IWorkbook workbook = application.Workbooks.Create(1);
            IWorksheet worksheet = workbook.Worksheets[0];

            //Add picture
            worksheet.Pictures.AddPicture("image.png");

            //Set picture
            IPictureShape picture = worksheet.Pictures["image"];

            //Set dimension
            picture.Left = 3;
            picture.Top = 3;
            picture.Height = 50;
            picture.Width = 50;

            //Save and dispose
            workbook.SaveAs("OLEObjects.xlsx");
            workbook.Close();
        }

